BMH.field = (label,path,{type='number',min=0,max=9999999999,step=1,scale=1,options=null,hint='',prefix='',suffix=''}={}) => {
  const value=BMH.get(path);
  return `<label class="field"><span>${label}</span><div class="field-control">${prefix?`<i>${prefix}</i>`:''}${options?`<select data-path="${path}">${options.map(o=>{const v=Array.isArray(o)?o[0]:o,n=Array.isArray(o)?o[1]:o;return `<option value="${BMH.esc(v)}" ${String(value)===String(v)?'selected':''}>${BMH.esc(n)}</option>`}).join('')}</select>`:`<input data-path="${path}" data-scale="${scale}" type="${type}" min="${min}" max="${max}" step="${step}" value="${type==='number'?Number(value)/scale:BMH.esc(value)}">`}${suffix?`<em>${suffix}</em>`:''}</div>${hint?`<small>${hint}</small>`:''}</label>`;
};
BMH.hero = (step,title,accent,desc,{quote='',banner=true}={}) => `<section class="step-hero step-hero-${step} ${banner?'with-banner':'plain'}"><div class="hero-copy"><span class="eyebrow">BƯỚC ${step} TRONG 10</span><h1>${title} ${accent?`<em>${accent}</em>`:''}</h1><p>${desc}</p></div>${banner?`<div class="hero-art hero-clean"><img src="assets/design/hero-step1.jpg" alt="Nhà hiện đại"><div class="hero-fade"></div>${quote?`<blockquote>“${quote}”</blockquote>`:''}</div>`:''}</section>`;
BMH.cardTitle = (title,desc='') => `<div class="card-title"><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>`;
BMH.sectionIcon = (char,title,desc='') => `<div class="section-heading"><i>${char}</i><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div></div>`;

BMH.compass = () => {
  const h=BMH.state.project.household, kua=BMH.kua(h.ownerBirth,h.ownerGender);
  const dirs=kua?.dirs||[];
  const good=new Set(dirs);
  const marks=[['Bắc',95,24],['Đông Bắc',153,45],['Đông',174,101],['Đông Nam',151,158],['Nam',95,180],['Tây Nam',38,158],['Tây',17,101],['Tây Bắc',39,45]];
  const labels=marks.map(([name,x,y])=>`<g class="compass-dir ${good.has(name)?'good':''}"><circle cx="${x}" cy="${y}" r="15"></circle><text x="${x}" y="${y+3}" text-anchor="middle">${name.replace('Đông ','Đ.').replace('Tây ','T.')}</text></g>`).join('');
  return `<div class="official-compass"><svg viewBox="0 0 190 205" role="img" aria-label="La bàn Bát Trạch tham khảo"><circle cx="95" cy="102" r="70" class="compass-ring"></circle><circle cx="95" cy="102" r="48" class="compass-ring inner"></circle><line x1="95" y1="32" x2="95" y2="172"></line><line x1="25" y1="102" x2="165" y2="102"></line><line x1="45" y1="52" x2="145" y2="152"></line><line x1="145" y1="52" x2="45" y2="152"></line><polygon class="needle-n" points="95,45 86,105 95,97 104,105"></polygon><polygon class="needle-s" points="95,159 86,99 95,107 104,99"></polygon><circle class="hub" cx="95" cy="102" r="6"></circle>${labels}<text x="95" y="10" text-anchor="middle" class="compass-title">BÁT TRẠCH THAM KHẢO</text></svg><div class="dir-list"><strong>Cung mệnh ${kua?`${kua.number} · ${kua.group}`:'chưa xác định'}</strong>${dirs.map((d,i)=>`<em><span>${['Sinh Khí','Thiên Y','Diên Niên','Phục Vị'][i]||'Hướng tốt'}</span><b>${d}</b></em>`).join('')}<small>Ưu tiên công năng, thông gió, ánh sáng và quy chuẩn xây dựng trước; phong thủy chỉ dùng như lớp tham khảo.</small></div></div>`;
};

